<template><SellerLayout><main class="management-page"><RouterLink class="text-link" to="/seller/products">Về sản phẩm và tồn kho</RouterLink><h1>{{ creating?'Tạo sản phẩm mới':'Tên, giá và gửi duyệt' }}</h1>
  <p>Sản phẩm mới được lưu nháp. Mô tả, thông số, ảnh và tồn kho dùng các trình sửa riêng; chỉ Admin duyệt sản phẩm để hiển thị công khai.</p>
  <p v-if="loading" role="status">Đang tải…</p><div v-if="error" role="alert" class="management-error">{{ error }} <button v-if="!loaded" class="button button-outline" @click="load">Thử lại</button></div><p v-if="success" role="status">{{ success }}</p>
  <form v-if="loaded" class="management-form" @submit.prevent="save"><label class="management-field">Tên sản phẩm<input v-model="form.name" required maxlength="180" :disabled="busy"/></label><label class="management-field">Giá bán (đồng)<input v-model="form.price" type="number" min="1" max="9999999999999.99" step="0.01" required :disabled="busy"/></label><label class="management-field">Danh mục<select v-model="form.categoryId" required :disabled="busy"><option value="">Chọn danh mục</option><option v-for="c in categories" :key="c.id" :value="c.id">{{ c.name }}</option></select></label><label class="management-field" v-if="creating">Tồn kho ban đầu<input v-model="form.stock" type="number" min="0" max="1000000" step="1" required :disabled="busy"/></label><p v-else>Trạng thái: {{ labels[state.status]||'Cần kiểm tra' }}. Sửa tên/giá sản phẩm đang hiển thị sẽ đưa về nháp để gửi duyệt lại. Đơn đã đặt giữ nguyên giá cũ.</p><button class="button button-primary" :disabled="busy">{{ busy?'Đang lưu…':creating?'Tạo bản nháp':'Lưu tên, giá và danh mục' }}</button></form>
  <section v-if="!creating&&loaded" class="market-panel"><h2>Hoàn thiện sản phẩm</h2><RouterLink class="button button-outline" :to="'/seller/products/'+id+'/content'">Sửa mô tả, thông số chậu và gallery</RouterLink><RouterLink class="button button-outline" to="/seller/products">Cập nhật tồn kho</RouterLink><p>Lưu mô tả, ít nhất một ảnh và tồn kho dương trước khi gửi duyệt. Hãy lưu tên/giá đang nhập trước.</p><button class="button button-primary" :disabled="busy||dirty||!['DRAFT','REJECTED'].includes(state.status)" @click="submit">Gửi Admin duyệt</button></section>
</main></SellerLayout></template>
<script setup>
import {ref,computed,onMounted} from 'vue';import {useRoute,useRouter,onBeforeRouteLeave} from 'vue-router';import SellerLayout from '../SellerLayout.vue';import {marketplaceRequest as request} from '../../../../services/marketplace.js';
const route=useRoute(),router=useRouter(),id=computed(()=>Number(route.params.id)),creating=computed(()=>!route.params.id),form=ref({name:'',price:'',categoryId:'',stock:0}),state=ref({}),categories=ref([]),loading=ref(false),busy=ref(false),loaded=ref(false),error=ref(''),success=ref(''),saved=ref(''),key=ref(crypto.randomUUID());
const labels={DRAFT:'Bản nháp',PENDING:'Chờ duyệt',ACTIVE:'Đang hiển thị',REJECTED:'Bị từ chối',ARCHIVED:'Đã lưu trữ'},dirty=computed(()=>JSON.stringify(form.value)!==saved.value);
async function load(){loading.value=true;error.value='';try{categories.value=await request('/categories');if(!creating.value){state.value=await request('/seller/products/'+id.value);form.value={name:state.value.name,price:state.value.price,categoryId:state.value.categoryId,stock:state.value.stock};}saved.value=JSON.stringify(form.value);loaded.value=true;}catch(e){error.value=e.message;}finally{loading.value=false;}}
async function save(){if(busy.value)return;busy.value=true;error.value='';success.value='';try{const body={name:form.value.name,price:Number(form.value.price),categoryId:Number(form.value.categoryId),...(creating.value?{stock:Number(form.value.stock),requestKey:key.value}:{revision:state.value.revision})};const value=await request('/seller/products'+(creating.value?'':'/'+id.value),creating.value?'POST':'PUT',body);saved.value=JSON.stringify(form.value);if(creating.value){busy.value=false;await router.replace('/seller/products/'+value.id+'/content');}else{state.value=value;success.value='Đã lưu. Bạn có thể hoàn thiện nội dung hoặc gửi duyệt.';}}catch(e){error.value=e.message+(e.status===409?' Bản nháp vẫn được giữ; tải lại trước khi quyết định ghi tiếp.':'');}finally{busy.value=false;}}
async function submit(){busy.value=true;error.value='';try{state.value=await request('/seller/products/'+id.value+'/submit','POST',{revision:state.value.revision});success.value='Đã gửi duyệt. Sản phẩm chưa hiển thị công khai.';}catch(e){error.value=e.message;}finally{busy.value=false;}}
onBeforeRouteLeave(()=>busy.value?false:!dirty.value||window.confirm('Rời trang và bỏ các thay đổi chưa lưu?'));onMounted(load);
</script>
